insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (21, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しあいに <u>勝ちます</u>。', '["かちます","まけます","うごきます","おもいます"]'::jsonb, 0, '勝ちます dibaca “かちます” dan berarti menang.', 'Bab 21–25 · Mondai 1 No.1', 'kanji:勝ちます'),
  (21, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃが <u>動きます</u>。', '["うごきます","かちます","まけます","おもいます"]'::jsonb, 0, '動きます dibaca “うごきます” dan berarti bergerak.', 'Bab 21–25 · Mondai 1 No.2', 'kanji:動きます'),
  (21, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'らいねん <u>留学します</u>。', '["りゅうがくします","きをつけます","やくにたちます","うごきます"]'::jsonb, 0, '留学します dibaca “りゅうがくします” dan berarti belajar di luar negeri.', 'Bab 21–25 · Mondai 1 No.3', 'kanji:留学します'),
  (21, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'セーターを <u>着ます</u>。', '["きます","はきます","かぶります","かけます"]'::jsonb, 0, '着ます dibaca “きます” dan berarti memakai (pakaian atas).', 'Bab 21–25 · Mondai 1 No.4', 'kanji:着ます'),
  (21, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもが <u>生まれます</u>。', '["うまれます","きます","かぶります","かけます"]'::jsonb, 0, '生まれます dibaca “うまれます” dan berarti lahir.', 'Bab 21–25 · Mondai 1 No.5', 'kanji:生まれます'),
  (21, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'みちを <u>渡ります</u>。', '["わたります","あるきます","まがります","さわります"]'::jsonb, 0, '渡ります dibaca “わたります” dan berarti menyeberang.', 'Bab 21–25 · Mondai 1 No.6', 'kanji:渡ります'),
  (21, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'つぎの かどを <u>曲がります</u>。', '["まがります","わたります","あるきます","でます"]'::jsonb, 0, '曲がります dibaca “まがります” dan berarti belok.', 'Bab 21–25 · Mondai 1 No.7', 'kanji:曲がります'),
  (21, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいに ちずを <u>説明します</u>。', '["せつめいします","しょうかいします","あんないします","なおします"]'::jsonb, 0, '説明します dibaca “せつめいします” dan berarti menjelaskan.', 'Bab 21–25 · Mondai 1 No.8', 'kanji:説明します'),
  (21, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちを かぞくに <u>紹介します</u>。', '["しょうかいします","あんないします","せつめいします","なおします"]'::jsonb, 0, '紹介します dibaca “しょうかいします” dan berarti memperkenalkan.', 'Bab 21–25 · Mondai 1 No.9', 'kanji:紹介します'),
  (21, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '10じに えきに <u>着きます</u>。', '["つきます","かんがえます","たります","とります"]'::jsonb, 0, '着きます dibaca “つきます” dan berarti tiba/sampai.', 'Bab 21–25 · Mondai 1 No.10', 'kanji:着きます'),
  (21, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんごが <u>やくにたちます</u>。', '["役に立ちます","動きます","勝ちます","負けます"]'::jsonb, 0, 'やくにたちます ditulis 役に立ちます, berarti bermanfaat.', 'Bab 21–25 · Mondai 2 No.11', 'kanji:役に立ちます'),
  (21, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くるまに <u>きをつけます</u>。', '["気を付けます","役に立ちます","動きます","思います"]'::jsonb, 0, 'きをつけます ditulis 気を付けます, berarti berhati-hati.', 'Bab 21–25 · Mondai 2 No.12', 'kanji:気を付けます'),
  (21, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あたらしい <u>ぼうし</u>を かいました。', '["帽子","眼鏡","上着","靴下"]'::jsonb, 0, 'ぼうし ditulis 帽子, berarti topi.', 'Bab 21–25 · Mondai 2 No.13', 'kanji:帽子'),
  (21, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くるまが <u>こしょう</u>しました。', '["故障","信号","交差点","道"]'::jsonb, 0, 'こしょう ditulis 故障, berarti kerusakan.', 'Bab 21–25 · Mondai 2 No.14', 'kanji:故障'),
  (21, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>しんごう</u>が あかです。', '["信号","交差点","建物","駐車場"]'::jsonb, 0, 'しんごう ditulis 信号, berarti lampu lalu lintas.', 'Bab 21–25 · Mondai 2 No.15', 'kanji:信号'),
  (21, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'えきまで ともだちを <u>おくりました</u>。', '["送りました","紹介しました","案内しました","説明しました"]'::jsonb, 0, 'おくりました ditulis 送りました, berarti mengantar (orang).', 'Bab 21–25 · Mondai 2 No.16', 'kanji:送ります'),
  (21, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'よく <u>かんがえました</u>。', '["考えました","着きました","足りました","取りました"]'::jsonb, 0, 'かんがえました ditulis 考えました, berarti memikirkan.', 'Bab 21–25 · Mondai 2 No.17', 'kanji:考えます'),
  (21, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おかねが <u>たりません</u>。', '["足りません","着きません","考えません","取りません"]'::jsonb, 0, 'たりません ditulis 足りません, berarti tidak cukup.', 'Bab 21–25 · Mondai 2 No.18', 'kanji:足ります'),
  (21, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しごとを <u>がんばります</u>。', '["頑張ります","考えます","着きます","足ります"]'::jsonb, 0, 'がんばります ditulis 頑張ります, berarti berusaha/bekerja keras.', 'Bab 21–25 · Mondai 2 No.19', 'kanji:頑張ります'),
  (21, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>めがね</u>を かけます。', '["眼鏡","帽子","上着","靴下"]'::jsonb, 0, 'めがね ditulis 眼鏡, berarti kacamata.', 'Bab 21–25 · Mondai 2 No.20', 'kanji:眼鏡'),
  (21, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>と</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>あした</span><span class="arrange-chip"><b>⑤</b>ふる</span><span class="arrange-chip"><b>⑥</b>は</span><span class="arrange-chip"><b>⑦</b>おもいます。</span></div><small>Petunjuk arti: “Saya kira besok akan hujan.”</small>', '["④→⑥→②→③→⑤→①→⑦","⑥→④→②→③→⑤→①→⑦","④→②→⑥→③→⑤→①→⑦","④→⑥→③→②→⑤→①→⑦"]'::jsonb, 0, 'Urutan yang benar: ④あした→⑥は→②あめ→③が→⑤ふる→①と→⑦おもいます。 と menandai isi dugaan sebelum おもいます, bentuk negatif diletakkan langsung sebelum と (Pel.21).', 'Bab 21–25 · Mondai 3 No.21', 'materi:book1:20:0'),
  (21, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>とうきょう</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>あります。</span><span class="arrange-chip"><b>④</b>で</span><span class="arrange-chip"><b>⑤</b>サッカー</span><span class="arrange-chip"><b>⑥</b>しあい</span><span class="arrange-chip"><b>⑦</b>が</span></div><small>Petunjuk arti: “Di Tokyo diadakan pertandingan sepak bola.”</small>', '["①→④→⑤→②→⑥→⑦→③","④→①→⑤→②→⑥→⑦→③","①→⑤→④→②→⑥→⑦→③","①→④→②→⑤→⑥→⑦→③"]'::jsonb, 0, 'Urutan yang benar: ①とうきょう→④で→⑤サッカー→②の→⑥しあい→⑦が→③あります。 で menandai tempat terjadinya suatu acara/peristiwa bersama あります (Pel.21).', 'Bab 21–25 · Mondai 3 No.22', 'materi:book1:20:0'),
  (21, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ビール</span><span class="arrange-chip"><b>②</b>のみませんか。</span><span class="arrange-chip"><b>③</b>ちょっと</span><span class="arrange-chip"><b>④</b>でも</span></div><small>Petunjuk arti: “Bagaimana kalau minum bir?”</small>', '["③→①→④→②","①→③→④→②","③→④→①→②","③→①→②→④"]'::jsonb, 0, 'Urutan yang benar: ③ちょっと→①ビール→④でも→②のみませんか。 でも dipakai untuk menyebut satu contoh saja ketika mengajak atau menawarkan sesuatu (Pel.21).', 'Bab 21–25 · Mondai 3 No.23', 'materi:book1:20:0'),
  (21, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>つくった</span><span class="arrange-chip"><b>②</b>ケーキ</span><span class="arrange-chip"><b>③</b>これ</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>が</span><span class="arrange-chip"><b>⑥</b>です。</span><span class="arrange-chip"><b>⑦</b>ミラーさん</span></div><small>Petunjuk arti: “Ini kue yang dibuat oleh Sdr. Miller.”</small>', '["③→④→⑦→⑤→①→②→⑥","④→③→⑦→⑤→①→②→⑥","③→⑦→④→⑤→①→②→⑥","③→④→⑤→⑦→①→②→⑥"]'::jsonb, 0, 'Urutan yang benar: ③これ→④は→⑦ミラーさん→⑤が→①つくった→②ケーキ→⑥です。 が menandai subjek DI DALAM anak kalimat yang menerangkan kata benda, berbeda dari は yang menandai topik kalimat utama (Pel.22).', 'Bab 21–25 · Mondai 3 No.24', 'materi:book1:21:0'),
  (21, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>へ</span><span class="arrange-chip"><b>②</b>と</span><span class="arrange-chip"><b>③</b>みぎ</span><span class="arrange-chip"><b>④</b>まがる</span><span class="arrange-chip"><b>⑤</b>ゆうびんきょく</span><span class="arrange-chip"><b>⑥</b>あります。</span><span class="arrange-chip"><b>⑦</b>が</span></div><small>Petunjuk arti: “Kalau belok kanan, ada kantor pos.”</small>', '["③→①→④→②→⑤→⑦→⑥","①→③→④→②→⑤→⑦→⑥","③→④→①→②→⑤→⑦→⑥","③→①→②→④→⑤→⑦→⑥"]'::jsonb, 0, 'Urutan yang benar: ③みぎ→①へ→④まがる→②と→⑤ゆうびんきょく→⑦が→⑥あります。 と menyatakan hasil yang pasti/alami terjadi setelah suatu aksi (Pel.23).', 'Bab 21–25 · Mondai 3 No.25', 'materi:book1:22:0'),
  (21, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>みぎ</span><span class="arrange-chip"><b>②</b>へ</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>まがります。</span><span class="arrange-chip"><b>⑤</b>こうさてん</span></div><small>Petunjuk arti: “Di perempatan belok ke kanan.”</small>', '["⑤→③→①→②→④","③→⑤→①→②→④","⑤→①→③→②→④","⑤→③→②→①→④"]'::jsonb, 0, 'Urutan yang benar: ⑤こうさてん→③を→①みぎ→②へ→④まがります。 を dipakai bersama Kata Kerja gerakan berpindah seperti まがります, menandai tempat yang dilewati (Pel.23).', 'Bab 21–25 · Mondai 3 No.26', 'materi:book1:22:0'),
  (21, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わたし</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>クリスマスカード</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>くれました。</span><span class="arrange-chip"><b>⑦</b>さとうさん</span></div><small>Petunjuk arti: “Sdr. Sato memberi saya kartu Natal.”</small>', '["⑦→③→①→②→④→⑤→⑥","③→⑦→①→②→④→⑤→⑥","⑦→①→③→②→④→⑤→⑥","⑦→③→②→①→④→⑤→⑥"]'::jsonb, 0, 'Urutan yang benar: ⑦さとうさん→③は→①わたし→②に→④クリスマスカード→⑤を→⑥くれました。 に menandai penerima dalam pola kalimat くれます, dipakai kalau ORANG LAIN memberi ke pembicara/keluarganya (Pel.24).', 'Bab 21–25 · Mondai 3 No.27', 'materi:book1:23:0'),
  (21, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>くれました。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>ワイン</span><span class="arrange-chip"><b>⑤</b>さとうさん</span><span class="arrange-chip"><b>⑥</b>この</span></div><small>Petunjuk arti: “Anggur ini, Sdr. Sato yang memberikannya.”</small>', '["⑥→④→③→⑤→①→②","④→⑥→③→⑤→①→②","⑥→③→④→⑤→①→②","⑥→④→⑤→③→①→②"]'::jsonb, 0, 'Urutan yang benar: ⑥この→④ワイン→③は→⑤さとうさん→①が→②くれました。 が menandai subjek/pemberi dalam pola N1は N2が くれました (Pel.24).', 'Bab 21–25 · Mondai 3 No.28', 'materi:book1:23:0'),
  (21, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>りょこうします。</span><span class="arrange-chip"><b>②</b>おかね</span><span class="arrange-chip"><b>③</b>あったら</span><span class="arrange-chip"><b>④</b>が</span></div><small>Petunjuk arti: “Kalau punya uang, akan berwisata.”</small>', '["②→④→③→①","④→②→③→①","②→③→④→①","②→④→①→③"]'::jsonb, 0, 'Urutan yang benar: ②おかね→④が→③あったら→①りょこうします。 たら (dari Bentuk Biasa Lampau + ら) menyatakan pengandaian, disusul kalimat pokok berupa keinginan/rencana (Pel.25).', 'Bab 21–25 · Mondai 3 No.29', 'materi:book1:24:0'),
  (21, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>せんたくします。</span><span class="arrange-chip"><b>②</b>ふっても</span><span class="arrange-chip"><b>③</b>あめ</span><span class="arrange-chip"><b>④</b>が</span></div><small>Petunjuk arti: “Walaupun hujan, mencuci pakaian.”</small>', '["③→④→②→①","④→③→②→①","③→②→④→①","③→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ③あめ→④が→②ふっても→①せんたくします。 ても menyatakan bahwa hasilnya TIDAK berubah walaupun syarat yang berlawanan terjadi (Pel.25).', 'Bab 21–25 · Mondai 3 No.30', 'materi:book1:24:0'),
  (21, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ミラーさん</span><span class="arrange-chip"><b>②</b>ニュース</span><span class="arrange-chip"><b>③</b>と</span><span class="arrange-chip"><b>④</b>おもいます。</span><span class="arrange-chip"><b>⑤</b>この</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>は</span><span class="arrange-chip"><b>⑧</b>しらない</span></div><small>Petunjuk arti: “Saya kira Sdr. Miller tidak tahu berita ini.”</small>', '["①→⑦→⑤→②→⑥→⑧→③→④","⑦→①→⑤→②→⑥→⑧→③→④","①→⑤→⑦→②→⑥→⑧→③→④","①→⑦→②→⑤→⑥→⑧→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ミラーさん→⑦は→⑤この→②ニュース→⑥を→⑧しらない→③と→④おもいます。 Bentuk negatif diletakkan langsung sebelum と dalam pola ～と思います untuk menyatakan dugaan negatif (Pel.21).', 'Bab 21–25 · Mondai 4 No.31', 'materi:book1:20:0'),
  (21, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ミラーさん</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>かいました。</span><span class="arrange-chip"><b>⑤</b>すんでいた</span><span class="arrange-chip"><b>⑥</b>うち</span></div><small>Petunjuk arti: “Membeli rumah yang dihuni Sdr. Miller.”</small>', '["①→②→⑤→⑥→③→④","②→①→⑤→⑥→③→④","①→⑤→②→⑥→③→④","①→②→⑥→⑤→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ミラーさん→②が→⑤すんでいた→⑥うち→③を→④かいました。 Anak kalimat「ミラーさんがすんでいた」menerangkan うち (rumah) langsung di depannya, subjek anak kalimat ditandai が (Pel.22).', 'Bab 21–25 · Mondai 4 No.32', 'materi:book1:21:0'),
  (21, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>とき</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>かりる</span><span class="arrange-chip"><b>④</b>が</span><span class="arrange-chip"><b>⑤</b>カード</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>ほん</span><span class="arrange-chip"><b>⑧</b>としょかん</span><span class="arrange-chip"><b>⑨</b>いります。</span></div><small>Petunjuk arti: “Ketika meminjam buku di perpustakaan, diperlukan kartu.”</small>', '["⑧→②→⑦→⑥→③→①→⑤→④→⑨","②→⑧→⑦→⑥→③→①→⑤→④→⑨","⑧→⑦→②→⑥→③→①→⑤→④→⑨","⑧→②→⑥→⑦→③→①→⑤→④→⑨"]'::jsonb, 0, 'Urutan yang benar: ⑧としょかん→②で→⑦ほん→⑥を→③かりる→①とき→⑤カード→④が→⑨いります。 とき didahului Kata Kerja bentuk kamus untuk menyatakan waktu ketika suatu keadaan terjadi (Pel.23).', 'Bab 21–25 · Mondai 4 No.33', 'materi:book1:22:0'),
  (21, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>やまださん</span><span class="arrange-chip"><b>②</b>もらいました。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>おしえて</span><span class="arrange-chip"><b>⑤</b>に</span><span class="arrange-chip"><b>⑥</b>わたし</span><span class="arrange-chip"><b>⑦</b>を</span><span class="arrange-chip"><b>⑧</b>でんわばんごう</span></div><small>Petunjuk arti: “Saya diberitahu nomor telepon oleh Sdr. Yamada.”</small>', '["⑥→③→①→⑤→⑧→⑦→④→②","③→⑥→①→⑤→⑧→⑦→④→②","⑥→①→③→⑤→⑧→⑦→④→②","⑥→③→⑤→①→⑧→⑦→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑥わたし→③は→①やまださん→⑤に→⑧でんわばんごう→⑦を→④おしえて→②もらいました。 Kata Kerja bentuk てもらいます menunjukkan pembicara menerima kebaikan, penerima kebaikan dijadikan subjek (Pel.24).', 'Bab 21–25 · Mondai 4 No.34', 'materi:book1:23:0'),
  (21, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>もし</span><span class="arrange-chip"><b>②</b>いろいろな</span><span class="arrange-chip"><b>③</b>くに</span><span class="arrange-chip"><b>④</b>りょこうしたいです。</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>いちおくえん</span><span class="arrange-chip"><b>⑦</b>あったら</span></div><small>Petunjuk arti: “Kalau punya seratus juta yen, ingin berwisata di berbagai negara.”</small>', '["①→⑥→⑦→②→③→⑤→④","⑥→①→⑦→②→③→⑤→④","①→⑦→⑥→②→③→⑤→④","①→⑥→②→⑦→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①もし→⑥いちおくえん→⑦あったら→②いろいろな→③くに→⑤を→④りょこうしたいです。 もし menegaskan bahwa kalimat berikutnya adalah pengandaian, selalu berpasangan dengan ～たら (Pel.25).', 'Bab 21–25 · Mondai 4 No.35', 'materi:book1:24:0'),
  (21, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、あした　あめが　ふると　おもいます。ミラーさんは「あしたは　はれます」と　いいました。<br><small>ミラーさんは　なんと　いいましたか。</small>', '["あめが　ふる","はれます","あついです","わかりません"]'::jsonb, 1, 'と言います mengutip perkataan LANGSUNG orang lain（「あしたははれます」）, berbeda dari と思います yang menyatakan pendapat SI PEMBICARA sendiri (Pel.21).', 'Bab 21–25 · Soal Cerita No.36', 'materi:book1:20:0'),
  (21, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、カリナさんが　かいた　えが　すきです。カリナさんは、えが　じょうずです。<br><small>だれが　えを　かきましたか。</small>', '["わたし","カリナさん","せんせい","ともだち"]'::jsonb, 1, 'Dalam anak kalimat「カリナさんがかいた」(yang dilukis Karina), subjek anak kalimat ditandai が, jadi Karina-lah yang melukis, bukan わたし yang hanya menyatakan suka (Pel.22).', 'Bab 21–25 · Soal Cerita No.37', 'materi:book1:21:0'),
  (21, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'パリへ　いく　とき、かばんを　かいました。パリへ　いった　とき、とけいを　かいました。<br><small>かばんを　かったのは、どこですか。</small>', '["パリ","パリへ いく まえの、とちゅうの どこか","にほん","わかりません"]'::jsonb, 1, 'とき dengan Kata Kerja BENTUK KAMUS（いくとき）menunjukkan hal yang terjadi SEBELUM tiba, sedangkan BENTUK た（いったとき）menunjukkan hal yang terjadi SETELAH tiba — jadi かばん dibeli DALAM PERJALANAN, sedangkan とけい dibeli DI Paris (Pel.23).', 'Bab 21–25 · Soal Cerita No.38', 'materi:book1:22:0'),
  (21, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、きむらさんに　ほんを　かして　あげました。やまださんは、わたしに　でんわばんごうを　おしえて　くれました。<br><small>だれが　わたしに　なにかを　して　くれましたか。</small>', '["きむらさん","やまださん","わたし","せんせい"]'::jsonb, 1, '「てあげます」berarti SAYA memberi kebaikan kepada Kimura, sedangkan「てくれます」berarti Yamada YANG memberi kebaikan kepada saya — dua arah pemberian yang berbeda (Pel.24).', 'Bab 21–25 · Soal Cerita No.39', 'materi:book1:23:0'),
  (21, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'おかねが　あったら、りょこうします。でも、いそがしくても、やすみを　とりません。<br><small>いそがしい　とき、やすみを　とりますか。</small>', '["はい、とります","いいえ、とりません","おかねが あれば、とります","わかりません"]'::jsonb, 1, '「いそがしくても、やすみをとりません」(walaupun sibuk, tidak mengambil cuti) — pola ても menyatakan hasil yang TIDAK berubah meski kondisinya berlawanan dari dugaan, berbeda dari たら yang menyatakan syarat (Pel.25).', 'Bab 21–25 · Soal Cerita No.40', 'materi:book1:24:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (21, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しあいに <u>勝ちます</u>。', '["かちます","まけます","うごきます","おもいます"]'::jsonb, 0, '勝ちます dibaca “かちます” dan berarti menang.', 'Bab 21–25 · Mondai 1 No.1', 'kanji:勝ちます'),
  (21, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃが <u>動きます</u>。', '["うごきます","かちます","まけます","おもいます"]'::jsonb, 0, '動きます dibaca “うごきます” dan berarti bergerak.', 'Bab 21–25 · Mondai 1 No.2', 'kanji:動きます'),
  (21, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'らいねん <u>留学します</u>。', '["りゅうがくします","きをつけます","やくにたちます","うごきます"]'::jsonb, 0, '留学します dibaca “りゅうがくします” dan berarti belajar di luar negeri.', 'Bab 21–25 · Mondai 1 No.3', 'kanji:留学します'),
  (21, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'セーターを <u>着ます</u>。', '["きます","はきます","かぶります","かけます"]'::jsonb, 0, '着ます dibaca “きます” dan berarti memakai (pakaian atas).', 'Bab 21–25 · Mondai 1 No.4', 'kanji:着ます'),
  (21, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもが <u>生まれます</u>。', '["うまれます","きます","かぶります","かけます"]'::jsonb, 0, '生まれます dibaca “うまれます” dan berarti lahir.', 'Bab 21–25 · Mondai 1 No.5', 'kanji:生まれます'),
  (21, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'みちを <u>渡ります</u>。', '["わたります","あるきます","まがります","さわります"]'::jsonb, 0, '渡ります dibaca “わたります” dan berarti menyeberang.', 'Bab 21–25 · Mondai 1 No.6', 'kanji:渡ります'),
  (21, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'つぎの かどを <u>曲がります</u>。', '["まがります","わたります","あるきます","でます"]'::jsonb, 0, '曲がります dibaca “まがります” dan berarti belok.', 'Bab 21–25 · Mondai 1 No.7', 'kanji:曲がります'),
  (21, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいに ちずを <u>説明します</u>。', '["せつめいします","しょうかいします","あんないします","なおします"]'::jsonb, 0, '説明します dibaca “せつめいします” dan berarti menjelaskan.', 'Bab 21–25 · Mondai 1 No.8', 'kanji:説明します'),
  (21, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちを かぞくに <u>紹介します</u>。', '["しょうかいします","あんないします","せつめいします","なおします"]'::jsonb, 0, '紹介します dibaca “しょうかいします” dan berarti memperkenalkan.', 'Bab 21–25 · Mondai 1 No.9', 'kanji:紹介します'),
  (21, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '10じに えきに <u>着きます</u>。', '["つきます","かんがえます","たります","とります"]'::jsonb, 0, '着きます dibaca “つきます” dan berarti tiba/sampai.', 'Bab 21–25 · Mondai 1 No.10', 'kanji:着きます'),
  (21, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にほんごが <u>やくにたちます</u>。', '["役に立ちます","動きます","勝ちます","負けます"]'::jsonb, 0, 'やくにたちます ditulis 役に立ちます, berarti bermanfaat.', 'Bab 21–25 · Mondai 2 No.11', 'kanji:役に立ちます'),
  (21, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くるまに <u>きをつけます</u>。', '["気を付けます","役に立ちます","動きます","思います"]'::jsonb, 0, 'きをつけます ditulis 気を付けます, berarti berhati-hati.', 'Bab 21–25 · Mondai 2 No.12', 'kanji:気を付けます'),
  (21, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あたらしい <u>ぼうし</u>を かいました。', '["帽子","眼鏡","上着","靴下"]'::jsonb, 0, 'ぼうし ditulis 帽子, berarti topi.', 'Bab 21–25 · Mondai 2 No.13', 'kanji:帽子'),
  (21, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'くるまが <u>こしょう</u>しました。', '["故障","信号","交差点","道"]'::jsonb, 0, 'こしょう ditulis 故障, berarti kerusakan.', 'Bab 21–25 · Mondai 2 No.14', 'kanji:故障'),
  (21, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>しんごう</u>が あかです。', '["信号","交差点","建物","駐車場"]'::jsonb, 0, 'しんごう ditulis 信号, berarti lampu lalu lintas.', 'Bab 21–25 · Mondai 2 No.15', 'kanji:信号'),
  (21, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'えきまで ともだちを <u>おくりました</u>。', '["送りました","紹介しました","案内しました","説明しました"]'::jsonb, 0, 'おくりました ditulis 送りました, berarti mengantar (orang).', 'Bab 21–25 · Mondai 2 No.16', 'kanji:送ります'),
  (21, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'よく <u>かんがえました</u>。', '["考えました","着きました","足りました","取りました"]'::jsonb, 0, 'かんがえました ditulis 考えました, berarti memikirkan.', 'Bab 21–25 · Mondai 2 No.17', 'kanji:考えます'),
  (21, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'おかねが <u>たりません</u>。', '["足りません","着きません","考えません","取りません"]'::jsonb, 0, 'たりません ditulis 足りません, berarti tidak cukup.', 'Bab 21–25 · Mondai 2 No.18', 'kanji:足ります'),
  (21, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'しごとを <u>がんばります</u>。', '["頑張ります","考えます","着きます","足ります"]'::jsonb, 0, 'がんばります ditulis 頑張ります, berarti berusaha/bekerja keras.', 'Bab 21–25 · Mondai 2 No.19', 'kanji:頑張ります'),
  (21, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>めがね</u>を かけます。', '["眼鏡","帽子","上着","靴下"]'::jsonb, 0, 'めがね ditulis 眼鏡, berarti kacamata.', 'Bab 21–25 · Mondai 2 No.20', 'kanji:眼鏡'),
  (21, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>と</span><span class="arrange-chip"><b>②</b>あめ</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>あした</span><span class="arrange-chip"><b>⑤</b>ふる</span><span class="arrange-chip"><b>⑥</b>は</span><span class="arrange-chip"><b>⑦</b>おもいます。</span></div><small>Petunjuk arti: “Saya kira besok akan hujan.”</small>', '["④→⑥→②→③→⑤→①→⑦","⑥→④→②→③→⑤→①→⑦","④→②→⑥→③→⑤→①→⑦","④→⑥→③→②→⑤→①→⑦"]'::jsonb, 0, 'Urutan yang benar: ④あした→⑥は→②あめ→③が→⑤ふる→①と→⑦おもいます。 と menandai isi dugaan sebelum おもいます, bentuk negatif diletakkan langsung sebelum と (Pel.21).', 'Bab 21–25 · Mondai 3 No.21', 'materi:book1:20:0'),
  (21, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>とうきょう</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>あります。</span><span class="arrange-chip"><b>④</b>で</span><span class="arrange-chip"><b>⑤</b>サッカー</span><span class="arrange-chip"><b>⑥</b>しあい</span><span class="arrange-chip"><b>⑦</b>が</span></div><small>Petunjuk arti: “Di Tokyo diadakan pertandingan sepak bola.”</small>', '["①→④→⑤→②→⑥→⑦→③","④→①→⑤→②→⑥→⑦→③","①→⑤→④→②→⑥→⑦→③","①→④→②→⑤→⑥→⑦→③"]'::jsonb, 0, 'Urutan yang benar: ①とうきょう→④で→⑤サッカー→②の→⑥しあい→⑦が→③あります。 で menandai tempat terjadinya suatu acara/peristiwa bersama あります (Pel.21).', 'Bab 21–25 · Mondai 3 No.22', 'materi:book1:20:0'),
  (21, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ビール</span><span class="arrange-chip"><b>②</b>のみませんか。</span><span class="arrange-chip"><b>③</b>ちょっと</span><span class="arrange-chip"><b>④</b>でも</span></div><small>Petunjuk arti: “Bagaimana kalau minum bir?”</small>', '["③→①→④→②","①→③→④→②","③→④→①→②","③→①→②→④"]'::jsonb, 0, 'Urutan yang benar: ③ちょっと→①ビール→④でも→②のみませんか。 でも dipakai untuk menyebut satu contoh saja ketika mengajak atau menawarkan sesuatu (Pel.21).', 'Bab 21–25 · Mondai 3 No.23', 'materi:book1:20:0'),
  (21, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>つくった</span><span class="arrange-chip"><b>②</b>ケーキ</span><span class="arrange-chip"><b>③</b>これ</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>が</span><span class="arrange-chip"><b>⑥</b>です。</span><span class="arrange-chip"><b>⑦</b>ミラーさん</span></div><small>Petunjuk arti: “Ini kue yang dibuat oleh Sdr. Miller.”</small>', '["③→④→⑦→⑤→①→②→⑥","④→③→⑦→⑤→①→②→⑥","③→⑦→④→⑤→①→②→⑥","③→④→⑤→⑦→①→②→⑥"]'::jsonb, 0, 'Urutan yang benar: ③これ→④は→⑦ミラーさん→⑤が→①つくった→②ケーキ→⑥です。 が menandai subjek DI DALAM anak kalimat yang menerangkan kata benda, berbeda dari は yang menandai topik kalimat utama (Pel.22).', 'Bab 21–25 · Mondai 3 No.24', 'materi:book1:21:0'),
  (21, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>へ</span><span class="arrange-chip"><b>②</b>と</span><span class="arrange-chip"><b>③</b>みぎ</span><span class="arrange-chip"><b>④</b>まがる</span><span class="arrange-chip"><b>⑤</b>ゆうびんきょく</span><span class="arrange-chip"><b>⑥</b>あります。</span><span class="arrange-chip"><b>⑦</b>が</span></div><small>Petunjuk arti: “Kalau belok kanan, ada kantor pos.”</small>', '["③→①→④→②→⑤→⑦→⑥","①→③→④→②→⑤→⑦→⑥","③→④→①→②→⑤→⑦→⑥","③→①→②→④→⑤→⑦→⑥"]'::jsonb, 0, 'Urutan yang benar: ③みぎ→①へ→④まがる→②と→⑤ゆうびんきょく→⑦が→⑥あります。 と menyatakan hasil yang pasti/alami terjadi setelah suatu aksi (Pel.23).', 'Bab 21–25 · Mondai 3 No.25', 'materi:book1:22:0'),
  (21, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>みぎ</span><span class="arrange-chip"><b>②</b>へ</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>まがります。</span><span class="arrange-chip"><b>⑤</b>こうさてん</span></div><small>Petunjuk arti: “Di perempatan belok ke kanan.”</small>', '["⑤→③→①→②→④","③→⑤→①→②→④","⑤→①→③→②→④","⑤→③→②→①→④"]'::jsonb, 0, 'Urutan yang benar: ⑤こうさてん→③を→①みぎ→②へ→④まがります。 を dipakai bersama Kata Kerja gerakan berpindah seperti まがります, menandai tempat yang dilewati (Pel.23).', 'Bab 21–25 · Mondai 3 No.26', 'materi:book1:22:0'),
  (21, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わたし</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>クリスマスカード</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>くれました。</span><span class="arrange-chip"><b>⑦</b>さとうさん</span></div><small>Petunjuk arti: “Sdr. Sato memberi saya kartu Natal.”</small>', '["⑦→③→①→②→④→⑤→⑥","③→⑦→①→②→④→⑤→⑥","⑦→①→③→②→④→⑤→⑥","⑦→③→②→①→④→⑤→⑥"]'::jsonb, 0, 'Urutan yang benar: ⑦さとうさん→③は→①わたし→②に→④クリスマスカード→⑤を→⑥くれました。 に menandai penerima dalam pola kalimat くれます, dipakai kalau ORANG LAIN memberi ke pembicara/keluarganya (Pel.24).', 'Bab 21–25 · Mondai 3 No.27', 'materi:book1:23:0'),
  (21, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>くれました。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>ワイン</span><span class="arrange-chip"><b>⑤</b>さとうさん</span><span class="arrange-chip"><b>⑥</b>この</span></div><small>Petunjuk arti: “Anggur ini, Sdr. Sato yang memberikannya.”</small>', '["⑥→④→③→⑤→①→②","④→⑥→③→⑤→①→②","⑥→③→④→⑤→①→②","⑥→④→⑤→③→①→②"]'::jsonb, 0, 'Urutan yang benar: ⑥この→④ワイン→③は→⑤さとうさん→①が→②くれました。 が menandai subjek/pemberi dalam pola N1は N2が くれました (Pel.24).', 'Bab 21–25 · Mondai 3 No.28', 'materi:book1:23:0'),
  (21, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>りょこうします。</span><span class="arrange-chip"><b>②</b>おかね</span><span class="arrange-chip"><b>③</b>あったら</span><span class="arrange-chip"><b>④</b>が</span></div><small>Petunjuk arti: “Kalau punya uang, akan berwisata.”</small>', '["②→④→③→①","④→②→③→①","②→③→④→①","②→④→①→③"]'::jsonb, 0, 'Urutan yang benar: ②おかね→④が→③あったら→①りょこうします。 たら (dari Bentuk Biasa Lampau + ら) menyatakan pengandaian, disusul kalimat pokok berupa keinginan/rencana (Pel.25).', 'Bab 21–25 · Mondai 3 No.29', 'materi:book1:24:0'),
  (21, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>せんたくします。</span><span class="arrange-chip"><b>②</b>ふっても</span><span class="arrange-chip"><b>③</b>あめ</span><span class="arrange-chip"><b>④</b>が</span></div><small>Petunjuk arti: “Walaupun hujan, mencuci pakaian.”</small>', '["③→④→②→①","④→③→②→①","③→②→④→①","③→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ③あめ→④が→②ふっても→①せんたくします。 ても menyatakan bahwa hasilnya TIDAK berubah walaupun syarat yang berlawanan terjadi (Pel.25).', 'Bab 21–25 · Mondai 3 No.30', 'materi:book1:24:0'),
  (21, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ミラーさん</span><span class="arrange-chip"><b>②</b>ニュース</span><span class="arrange-chip"><b>③</b>と</span><span class="arrange-chip"><b>④</b>おもいます。</span><span class="arrange-chip"><b>⑤</b>この</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>は</span><span class="arrange-chip"><b>⑧</b>しらない</span></div><small>Petunjuk arti: “Saya kira Sdr. Miller tidak tahu berita ini.”</small>', '["①→⑦→⑤→②→⑥→⑧→③→④","⑦→①→⑤→②→⑥→⑧→③→④","①→⑤→⑦→②→⑥→⑧→③→④","①→⑦→②→⑤→⑥→⑧→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ミラーさん→⑦は→⑤この→②ニュース→⑥を→⑧しらない→③と→④おもいます。 Bentuk negatif diletakkan langsung sebelum と dalam pola ～と思います untuk menyatakan dugaan negatif (Pel.21).', 'Bab 21–25 · Mondai 4 No.31', 'materi:book1:20:0'),
  (21, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ミラーさん</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>かいました。</span><span class="arrange-chip"><b>⑤</b>すんでいた</span><span class="arrange-chip"><b>⑥</b>うち</span></div><small>Petunjuk arti: “Membeli rumah yang dihuni Sdr. Miller.”</small>', '["①→②→⑤→⑥→③→④","②→①→⑤→⑥→③→④","①→⑤→②→⑥→③→④","①→②→⑥→⑤→③→④"]'::jsonb, 0, 'Urutan yang benar: ①ミラーさん→②が→⑤すんでいた→⑥うち→③を→④かいました。 Anak kalimat「ミラーさんがすんでいた」menerangkan うち (rumah) langsung di depannya, subjek anak kalimat ditandai が (Pel.22).', 'Bab 21–25 · Mondai 4 No.32', 'materi:book1:21:0'),
  (21, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>とき</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>かりる</span><span class="arrange-chip"><b>④</b>が</span><span class="arrange-chip"><b>⑤</b>カード</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>ほん</span><span class="arrange-chip"><b>⑧</b>としょかん</span><span class="arrange-chip"><b>⑨</b>いります。</span></div><small>Petunjuk arti: “Ketika meminjam buku di perpustakaan, diperlukan kartu.”</small>', '["⑧→②→⑦→⑥→③→①→⑤→④→⑨","②→⑧→⑦→⑥→③→①→⑤→④→⑨","⑧→⑦→②→⑥→③→①→⑤→④→⑨","⑧→②→⑥→⑦→③→①→⑤→④→⑨"]'::jsonb, 0, 'Urutan yang benar: ⑧としょかん→②で→⑦ほん→⑥を→③かりる→①とき→⑤カード→④が→⑨いります。 とき didahului Kata Kerja bentuk kamus untuk menyatakan waktu ketika suatu keadaan terjadi (Pel.23).', 'Bab 21–25 · Mondai 4 No.33', 'materi:book1:22:0'),
  (21, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>やまださん</span><span class="arrange-chip"><b>②</b>もらいました。</span><span class="arrange-chip"><b>③</b>は</span><span class="arrange-chip"><b>④</b>おしえて</span><span class="arrange-chip"><b>⑤</b>に</span><span class="arrange-chip"><b>⑥</b>わたし</span><span class="arrange-chip"><b>⑦</b>を</span><span class="arrange-chip"><b>⑧</b>でんわばんごう</span></div><small>Petunjuk arti: “Saya diberitahu nomor telepon oleh Sdr. Yamada.”</small>', '["⑥→③→①→⑤→⑧→⑦→④→②","③→⑥→①→⑤→⑧→⑦→④→②","⑥→①→③→⑤→⑧→⑦→④→②","⑥→③→⑤→①→⑧→⑦→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑥わたし→③は→①やまださん→⑤に→⑧でんわばんごう→⑦を→④おしえて→②もらいました。 Kata Kerja bentuk てもらいます menunjukkan pembicara menerima kebaikan, penerima kebaikan dijadikan subjek (Pel.24).', 'Bab 21–25 · Mondai 4 No.34', 'materi:book1:23:0'),
  (21, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>もし</span><span class="arrange-chip"><b>②</b>いろいろな</span><span class="arrange-chip"><b>③</b>くに</span><span class="arrange-chip"><b>④</b>りょこうしたいです。</span><span class="arrange-chip"><b>⑤</b>を</span><span class="arrange-chip"><b>⑥</b>いちおくえん</span><span class="arrange-chip"><b>⑦</b>あったら</span></div><small>Petunjuk arti: “Kalau punya seratus juta yen, ingin berwisata di berbagai negara.”</small>', '["①→⑥→⑦→②→③→⑤→④","⑥→①→⑦→②→③→⑤→④","①→⑦→⑥→②→③→⑤→④","①→⑥→②→⑦→③→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ①もし→⑥いちおくえん→⑦あったら→②いろいろな→③くに→⑤を→④りょこうしたいです。 もし menegaskan bahwa kalimat berikutnya adalah pengandaian, selalu berpasangan dengan ～たら (Pel.25).', 'Bab 21–25 · Mondai 4 No.35', 'materi:book1:24:0'),
  (21, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、あした　あめが　ふると　おもいます。ミラーさんは「あしたは　はれます」と　いいました。<br><small>ミラーさんは　なんと　いいましたか。</small>', '["あめが　ふる","はれます","あついです","わかりません"]'::jsonb, 1, 'と言います mengutip perkataan LANGSUNG orang lain（「あしたははれます」）, berbeda dari と思います yang menyatakan pendapat SI PEMBICARA sendiri (Pel.21).', 'Bab 21–25 · Soal Cerita No.36', 'materi:book1:20:0'),
  (21, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、カリナさんが　かいた　えが　すきです。カリナさんは、えが　じょうずです。<br><small>だれが　えを　かきましたか。</small>', '["わたし","カリナさん","せんせい","ともだち"]'::jsonb, 1, 'Dalam anak kalimat「カリナさんがかいた」(yang dilukis Karina), subjek anak kalimat ditandai が, jadi Karina-lah yang melukis, bukan わたし yang hanya menyatakan suka (Pel.22).', 'Bab 21–25 · Soal Cerita No.37', 'materi:book1:21:0'),
  (21, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'パリへ　いく　とき、かばんを　かいました。パリへ　いった　とき、とけいを　かいました。<br><small>かばんを　かったのは、どこですか。</small>', '["パリ","パリへ いく まえの、とちゅうの どこか","にほん","わかりません"]'::jsonb, 1, 'とき dengan Kata Kerja BENTUK KAMUS（いくとき）menunjukkan hal yang terjadi SEBELUM tiba, sedangkan BENTUK た（いったとき）menunjukkan hal yang terjadi SETELAH tiba — jadi かばん dibeli DALAM PERJALANAN, sedangkan とけい dibeli DI Paris (Pel.23).', 'Bab 21–25 · Soal Cerita No.38', 'materi:book1:22:0'),
  (21, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは、きむらさんに　ほんを　かして　あげました。やまださんは、わたしに　でんわばんごうを　おしえて　くれました。<br><small>だれが　わたしに　なにかを　して　くれましたか。</small>', '["きむらさん","やまださん","わたし","せんせい"]'::jsonb, 1, '「てあげます」berarti SAYA memberi kebaikan kepada Kimura, sedangkan「てくれます」berarti Yamada YANG memberi kebaikan kepada saya — dua arah pemberian yang berbeda (Pel.24).', 'Bab 21–25 · Soal Cerita No.39', 'materi:book1:23:0'),
  (21, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'おかねが　あったら、りょこうします。でも、いそがしくても、やすみを　とりません。<br><small>いそがしい　とき、やすみを　とりますか。</small>', '["はい、とります","いいえ、とりません","おかねが あれば、とります","わかりません"]'::jsonb, 1, '「いそがしくても、やすみをとりません」(walaupun sibuk, tidak mengambil cuti) — pola ても menyatakan hasil yang TIDAK berubah meski kondisinya berlawanan dari dugaan, berbeda dari たら yang menyatakan syarat (Pel.25).', 'Bab 21–25 · Soal Cerita No.40', 'materi:book1:24:0');
